PREFIX : <http://example.org/sfaa-wba-nbn-ethernet-price-list#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?downstreamPIR ?label
WHERE {
  ?avc a :AVC_TC4_ProductComponent ;
       :hasRecurringCharge ?charge ;
       :hasDownstreamPIR ?downstreamPIR .
  ?charge :hasAmount ?amount .
  ?amount :numericValue 12.00 .
  OPTIONAL { ?downstreamPIR rdfs:label ?label }
}

PREFIX : <http://example.org/sfaa-wba-nbn-ethernet-price-list#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?accessTechnology
WHERE {
  ?avc a :AVC_TC4_ProductComponent ;
       rdfs:label ?label ;
       :hasAccessTechnology ?accessTechnology .
  FILTER(CONTAINS(?label, "50/20"))
}

PREFIX : <http://example.org/sfaa-wba-nbn-ethernet-price-list#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?includedComponent ?componentLabel ?uniType ?networkType
WHERE {
  :UNI_Inclusion_Instance a :UNI_Inclusion ;
    :hasIncludedAVCTC1 ?includedAVC ;
    :hasUNI ?uni ;
    :conditionalOn ?network .
  ?includedAVC rdfs:label ?componentLabel .
  ?uni rdfs:label ?uniType .
  ?network rdfs:label ?networkType .
}

PREFIX : <http://example.org/sfaa-wba-nbn-ethernet-price-list#>

SELECT ?service ?label ?chargeRule ?sourceClause WHERE {
  ?service a :EnhancedFaultRectificationService .
  FILTER (?service != :EnhancedFaultRectification_Enhanced12_24_7)
  ?service rdfs:label ?label .
  OPTIONAL { ?service :sourceClause ?sourceClause . }
  BIND("nbn will charge RSP for that Alternative ESLA in accordance with the relevant Charge set out in section 2.2 or 9 (as applicable), in addition to the recurring Charge that applies to the TC-2 Bundle Components set out in the above table." AS ?chargeRule)
}

PREFIX : <http://example.org/sfaa-wba-nbn-ethernet-price-list#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?definition
WHERE {
  :OrderedBandwidth rdfs:comment ?definition .
}

PREFIX : <http://example.org/sfaa-wba-nbn-ethernet-price-list#>
SELECT ?network WHERE {
  :BasicOfferCondition_VNNI_NotSatellite :conditionDescription ?desc .
  FILTER(CONTAINS(LCASE(?desc), "not available") && CONTAINS(LCASE(?desc), "satellite"))
  BIND("nbn® Ethernet (Satellite)" AS ?network)
}

PREFIX : <http://example.org/sfaa-wba-nbn-ethernet-price-list#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?chargeAmount WHERE {
  ?service a :EnhancedFaultRectificationService ;
           rdfs:label "Enhanced Fault Rectification Service Enhanced-8" ;
           :hasRecurringCharge ?charge .
  ?charge :hasAmount ?amount .
  ?amount :numericValue ?chargeAmount .
  FILTER EXISTS { ?service :hasNetworkType :AccessTechnology_FIBRE }
}

PREFIX : <http://example.org/sfaa-wba-nbn-ethernet-price-list#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?chargeAmount
